CREATE TABLE authentication_attempts (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, user_id text NOT NULL REFERENCES users(id), purpose text NOT NULL CHECK (purpose IN ('invite_acceptance','login','password_change','recovery_regeneration')), second_factor text NOT NULL CHECK (second_factor IN ('otp','recovery')), first_methods text[] NOT NULL CHECK (array_length(first_methods,1)>0 AND first_methods <@ ARRAY['pwd','otp','recovery']), invite_id text REFERENCES invites(id), origin_session_id text, proposed_password_hash text, proposed_phone_e164 text, proposed_mfa_channel text CHECK(proposed_mfa_channel IS NULL OR proposed_mfa_channel IN ('sms','whatsapp')), verified_at timestamptz, expires_at timestamptz NOT NULL, consumed_at timestamptz, invalidated_at timestamptz, created_at timestamptz NOT NULL);
CREATE TABLE mfa_challenges (id text PRIMARY KEY, attempt_id text NOT NULL REFERENCES authentication_attempts(id), requested_channel text NOT NULL CHECK(requested_channel IN ('sms','whatsapp')), reported_channel text NOT NULL CHECK(reported_channel IN ('sms','whatsapp')), provider_challenge_id text NOT NULL CHECK(provider_challenge_id<>''), check_count integer NOT NULL DEFAULT 0 CHECK(check_count BETWEEN 0 AND 5), expires_at timestamptz NOT NULL, consumed_at timestamptz, invalidated_at timestamptz, created_at timestamptz NOT NULL);
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), amr text[] NOT NULL CHECK(array_length(amr,1)>0 AND amr <@ ARRAY['pwd','otp','recovery']), auth_time timestamptz NOT NULL, initial_ip_address inet, initial_user_agent text, last_used_at timestamptz NOT NULL, revoked_at timestamptz, ended_at timestamptz, created_at timestamptz NOT NULL, CHECK(revoked_at IS NULL OR ended_at IS NOT NULL));
CREATE TABLE refresh_tokens (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, session_id text NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, consumed_at timestamptz, successor_id text REFERENCES refresh_tokens(id), created_at timestamptz NOT NULL, CHECK(expires_at=created_at + interval '30 days'));
CREATE TABLE recovery_codes (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), code_hash text NOT NULL UNIQUE, generation integer NOT NULL CHECK(generation>0), used_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL);
UPDATE auth_schema_meta SET version=3, updated_at=now() WHERE singleton=true AND version<3;
